#!/bin/sh
# Build script for zxcc (the CP/M emulator from zxcc-0.5.7). zxcc runs
# CP/M .com files on the host by emulating a Z80 plus a subset of the
# CP/M 3 BDOS/BIOS. Only the emulator itself is built (the zxc/zxas/
# zxlibr/zxlink frontends are thin argument-converting wrappers around
# zxcc and are not needed for plain emulation).
#
# zxcc depends on the bundled cpmredir library (CP/M filesystem
# redirector). The optional cpmio layer (curses-based console I/O) is
# disabled, so ncurses is not required; console I/O falls back to plain
# stdio. The resulting binary is copied into ../bin (the project bin
# folder added to PATH by env.sh).
#
# Upstream: http://www.seasip.info/Unix/ZXCC/
# Source under vendor/zxcc-0.5.7/ is kept untouched; generated build
# artifacts (config.h, *.o, libcpmredir.a, the zxcc binary) are written
# to vendor/zxcc-0.5.7/build/ which is gitignored.
set -e

cd "$(dirname "$0")"            # -> vendor/

CC=${CC:-gcc}
# -std=gnu11 (pre-C23): upstream uses K&R-style unprototyped declarations
# like `unsigned int in();` which C23 would treat as `(void)` and reject
# the multi-argument calls in z80ops.h/edops.h.
CFLAGS=${CFLAGS:-"-O2 -Wall -std=gnu11"}
LDFLAGS=${LDFLAGS:-""}

SRC_DIR="$(pwd)/zxcc-0.5.7"
# Normalise ../bin to an absolute path so it can be baked into the
# binary as BINDIR80 (zxcc's first search directory for bios.bin and
# .com files) and used as the install target.
BIN_DIR="$(cd "$(pwd)/../bin" && pwd)"
BUILD_DIR="$SRC_DIR/build"

mkdir -p "$BIN_DIR" "$BUILD_DIR"

# config.h is normally generated by autoconf. We write a minimal one to
# $BUILD_DIR and point the compiler at it with -I. cpmio is left out so
# USE_CPMIO is not defined.
#
# BINDIR80 is pointed at the project's bin/ (with trailing slash, as
# zxcc concatenates it with filenames). The bundled bios.bin is copied
# there by this script, so `zxcc prog.com` finds it from any cwd after
# `. ./env.sh`. LIBDIR80/INCDIR80 keep the upstream defaults; they hold
# CP/M libraries/headers that are not bundled with this repo.
cat > "$BUILD_DIR/config.h" <<EOF
/* Generated by vendor/build-zxcc.sh. Minimal config.h for building
   zxcc without cpmio (curses) support. */
#define PACKAGE "zxcc"
#define PACKAGE_NAME "zxcc"
#define PACKAGE_TARNAME "zxcc"
#define PACKAGE_VERSION "0.5.7"
#define PACKAGE_STRING "zxcc 0.5.7"
#define PACKAGE_BUGREPORT ""
#define PACKAGE_URL ""
#define VERSION "0.5.7"
#define STDC_HEADERS 1
#define HAVE_STDLIB_H 1
#define HAVE_STRING_H 1
#define HAVE_MEMORY_H 1
#define HAVE_STRINGS_H 1
#define HAVE_INTTYPES_H 1
#define HAVE_STDINT_H 1
#define HAVE_SYS_STAT_H 1
#define HAVE_SYS_TYPES_H 1
#define HAVE_UNISTD_H 1
#define HAVE_FCNTL_H 1
#define HAVE_SYS_PARAM_H 1
#define HAVE_DIRENT_H 1
#define HAVE_UTIME_H 1
#define HAVE_SYS_VFS_H 1
#define HAVE_VPRINTF 1
#define HAVE_STRSTR 1
/* Runtime search directories for CP/M tools, libraries, headers and
   bios.bin. zxcc looks for bios.bin in BINDIR80 then the current
   directory. Change these and rebuild if you want a different layout. */
#define BINDIR80 "$BIN_DIR/"
#define LIBDIR80 "/usr/local/lib/cpm/lib80/"
#define INCDIR80 "/usr/local/lib/cpm/include80/"
EOF

# Shared include flags: generated config.h + cpmredir's public header.
INC="-I$BUILD_DIR -I$SRC_DIR/cpmredir/include"

# --- Build cpmredir static library (libcpmredir.a) ---
REDIR_LIB="$BUILD_DIR/libcpmredir.a"
cd "$SRC_DIR/cpmredir/lib"
REDIR_OBJS=""
for src in cpmdrv.c cpmglob.c cpmparse.c cpmredir.c drdos.c util.c xlt.c; do
  obj="$BUILD_DIR/redir_${src%.c}.o"
  $CC $CFLAGS $INC -DZXCC -c -o "$obj" "$src"
  REDIR_OBJS="$REDIR_OBJS $obj"
done
ar rcs "$REDIR_LIB" $REDIR_OBJS

# --- Build zxcc (the emulator) ---
# Sources per bin/Makefile.am's zxcc_SOURCES, minus cpmio.
cd "$SRC_DIR/bin"
ZXCC_OBJS=""
for src in z80.c zxbdos.c zxcbdos.c zxdbdos.c zxcc.c; do
  obj="$BUILD_DIR/${src%.c}.o"
  $CC $CFLAGS $INC -I. -DZXCC -c -o "$obj" "$src"
  ZXCC_OBJS="$ZXCC_OBJS $obj"
done

$CC $LDFLAGS -o "$BUILD_DIR/zxcc" $ZXCC_OBJS "$REDIR_LIB"

# Install into ../bin: the emulator and the vestigial CP/M BIOS it
# loads at startup (bios.bin). zxcc finds bios.bin via BINDIR80, which
# is compiled to point at this same bin/ directory.
cp -f "$BUILD_DIR/zxcc" "$BIN_DIR/"
cp -f "$SRC_DIR/Z80/bios.bin" "$BIN_DIR/"
echo "Built and copied zxcc to $BIN_DIR/zxcc (with bios.bin)"
